-- Benchmark data for ENG-2443. Test database only: it truncates the access tables.
-- psql variables: scale (rows per space = 1400 * scale), grants (ResourceAccess rows).
\set ON_ERROR_STOP 1
BEGIN;
TRUNCATE public."Space", public."PlatformAccount", public."ResourceAccess", public.group_membership CASCADE;
DELETE FROM auth.users WHERE email LIKE '%@bench.test';

CREATE TEMP TABLE bench_space AS
SELECT
    n,
    nextval('public.entity_id_seq')::bigint AS id,
    gen_random_uuid() AS uid
FROM generate_series(1, 20) AS n;

INSERT INTO auth.users (id, email, aud, role)
SELECT uid, 'space' || n || '@bench.test', 'authenticated', 'authenticated' FROM bench_space;
INSERT INTO auth.users (id, email, aud, role)
VALUES ('00000000-0000-4000-8000-0000000000a1', 'group@bench.test', 'authenticated', 'authenticated');

INSERT INTO public."Space" (id, url, name, platform)
SELECT id, 'https://bench.test/' || n, 'bench' || n, 'Roam' FROM bench_space;

INSERT INTO public."SpaceAccess" (account_uid, space_id, permissions)
SELECT uid, id, 'editor' FROM bench_space;
INSERT INTO public."SpaceAccess" (account_uid, space_id, permissions)
SELECT '00000000-0000-4000-8000-0000000000a1', id, CASE WHEN n = 2 THEN 'reader' ELSE 'partial' END::public."SpaceAccessPermissions"
FROM bench_space WHERE n >= 2;
INSERT INTO public.group_membership (group_id, member_id, admin)
SELECT '00000000-0000-4000-8000-0000000000a1', uid, false FROM bench_space WHERE n = 1;

CREATE TEMP TABLE bench_author AS
SELECT bs.id AS space_id, nextval('public.entity_id_seq')::bigint AS id, bs.n FROM bench_space AS bs;
INSERT INTO public."PlatformAccount" (id, name, platform, account_local_id)
SELECT id, 'author' || n, 'Roam', 'author' || n FROM bench_author;
INSERT INTO public."LocalAccess" (account_id, space_id) SELECT id, space_id FROM bench_author;

INSERT INTO public."Concept" (name, space_id, author_id, source_local_id, created, last_modified, is_schema, literal_content, reference_content)
SELECT 'c' || i, a.space_id, a.id, 'l' || i, now(), now(), true, '{}', '{}'
FROM bench_author AS a, generate_series(1, 1400 * :scale) AS i;

INSERT INTO public."Document" (space_id, author_id, source_local_id, created, last_modified)
SELECT a.space_id, a.id, 'l' || i, now(), now()
FROM bench_author AS a, generate_series(1, 1400 * :scale) AS i;

INSERT INTO public."Content" (document_id, space_id, author_id, source_local_id, variant, scale, text, created, last_modified)
SELECT d.id, d.space_id, d.author_id, d.source_local_id, 'direct', 'document', 'text ' || d.source_local_id, now(), now()
FROM public."Document" AS d;

-- Grants spread over the 18 partial spaces, one resource per grant.
INSERT INTO public."ResourceAccess" (account_uid, space_id, source_local_id)
SELECT '00000000-0000-4000-8000-0000000000a1', bs.id, 'l' || (k / 18 + 1)
FROM generate_series(0, :grants - 1) AS k
JOIN bench_space AS bs ON bs.n = 3 + (k % 18);

COMMIT;
ANALYZE;
SELECT
    (SELECT count(*) FROM public."Concept") AS concepts,
    (SELECT count(*) FROM public."Content") AS contents,
    (SELECT count(*) FROM public."ResourceAccess") AS grants;

-- Runs each query :runs times as the space-1 login under EXPLAIN ANALYZE, rolling back every run,
-- and returns the median execution time. Assumes bench.timings exists (setup.sql).
-- psql variable: phase ('before' or 'after').
\set ON_ERROR_STOP 1
SELECT
    bs.id AS own_space,
    (SELECT id FROM public."Space" WHERE name = 'bench2') AS reader_space,
    bs.uid AS caller,
    (SELECT id FROM public."PlatformAccount" WHERE name = 'author1') AS own_author
FROM pg_temp.bench_ids AS bs \gset
SELECT min(id) AS reader_content FROM public."Content" WHERE space_id = :reader_space \gset

SET role authenticated;
SELECT set_config('request.jwt.claims', json_build_object('sub', :'caller', 'role', 'authenticated')::text, false) IS NOT NULL AS claims;

SELECT bench.time_query(:'phase', 'concept own space', 'SELECT id FROM public."Concept" WHERE space_id = ' || :own_space);
SELECT bench.time_query(:'phase', 'concept other spaces', 'SELECT id FROM public."Concept" WHERE space_id <> ' || :own_space);
SELECT bench.time_query(:'phase', 'content by id', 'SELECT * FROM public."Content" WHERE id = ' || :reader_content);
SELECT bench.time_query(:'phase', 'insert 200 concepts',
    'INSERT INTO public."Concept" (name, space_id, author_id, source_local_id, created, last_modified, is_schema, literal_content, reference_content) '
    || 'SELECT ''new'' || g, ' || :own_space || ', ' || :own_author || ', ''new'' || g, now(), now(), true, ''{}'', ''{}'' FROM generate_series(1, 200) AS g');
SELECT bench.time_query(:'phase', 'update 200 concepts',
    'UPDATE public."Concept" SET last_modified = now() WHERE space_id = ' || :own_space
    || ' AND source_local_id IN (SELECT ''l'' || g FROM generate_series(1, 200) AS g)');
SELECT bench.time_query(:'phase', 'my_concepts other spaces', 'SELECT id FROM public.my_concepts WHERE space_id <> ' || :own_space);
SELECT bench.time_query(:'phase', 'my_contents other spaces', 'SELECT id FROM public.my_contents WHERE space_id <> ' || :own_space);
RESET role;

-- Measurement helpers in a throwaway schema. Drop with: DROP SCHEMA bench CASCADE;
\set ON_ERROR_STOP 1
DROP SCHEMA IF EXISTS bench CASCADE;
CREATE SCHEMA bench;
GRANT USAGE ON SCHEMA bench TO authenticated;
CREATE TABLE bench.timings (phase text, label text, scale text, ms numeric[], rows bigint);
GRANT INSERT, SELECT ON bench.timings TO authenticated;

-- Each run is rolled back by raising inside a sub-block; the timing survives in a plpgsql variable.
CREATE FUNCTION bench.time_query(phase text, label text, query text, runs int DEFAULT 7) RETURNS numeric
LANGUAGE plpgsql AS $$
DECLARE
    plan json;
    times numeric[] := '{}';
    row_count bigint;
BEGIN
    FOR i IN 1 .. runs + 1 LOOP
        BEGIN
            EXECUTE 'EXPLAIN (ANALYZE, FORMAT JSON) ' || query INTO plan;
            IF i > 1 THEN
                times := times || (plan -> 0 ->> 'Execution Time')::numeric;
            END IF;
            row_count := (plan -> 0 -> 'Plan' ->> 'Actual Rows')::bigint;
            RAISE EXCEPTION 'bench rollback';
        EXCEPTION WHEN raise_exception THEN
            NULL;
        END;
    END LOOP;
    INSERT INTO bench.timings VALUES (phase, label, current_setting('bench.scale', true), times, row_count);
    RETURN (SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY t) FROM unnest(times) AS t);
END;
$$;
GRANT EXECUTE ON FUNCTION bench.time_query TO authenticated;

