#!/bin/bash
# Usage: run.sh SCALE GRANTS ROUNDS. Test database only (generate.sql truncates access tables).
set -euo pipefail
cd "$(dirname "$0")"
DB="REDACTED"
docker ps --format '{{.Names}}' | grep -qx supabase_db_test || { echo "supabase_db_test is not running" >&2; exit 1; }
scale=$1 grants=$2 rounds=$3
psql "$DB" -q -t -A -v scale="$scale" -v grants="$grants" -f generate.sql
psql "$DB" -q -t -A -f setup.sql
for round in $(seq 1 "$rounds"); do
  psql "$DB" -q -t -A -v phase=before -c BEGIN -f revert.sql -f measure.sql -c ROLLBACK | grep '^RESULT' | sed "s/^/$scale|$grants|$round|/"
  psql "$DB" -q -t -A -v phase=after -f measure.sql | grep '^RESULT' | sed "s/^/$scale|$grants|$round|/"
done

-- Benchmark data for ENG-2443. Test database only: it truncates the access tables.
-- psql variables: scale (rows per space = 1400 * scale), grants (ResourceAccess rows).
\set ON_ERROR_STOP 1
BEGIN;
TRUNCATE public."Space", public."PlatformAccount", public."ResourceAccess", public.group_membership CASCADE;
DELETE FROM auth.users WHERE email LIKE '%@bench.test';

CREATE TEMP TABLE bench_space AS
SELECT
    n,
    nextval('public.entity_id_seq')::bigint AS id,
    gen_random_uuid() AS uid
FROM generate_series(1, 20) AS n;

INSERT INTO auth.users (id, email, aud, role)
SELECT uid, 'space' || n || '@bench.test', 'authenticated', 'authenticated' FROM bench_space;
INSERT INTO auth.users (id, email, aud, role)
VALUES ('00000000-0000-4000-8000-0000000000a1', 'group@bench.test', 'authenticated', 'authenticated');

INSERT INTO public."Space" (id, url, name, platform)
SELECT id, 'https://bench.test/' || n, 'bench' || n, 'Roam' FROM bench_space;

INSERT INTO public."SpaceAccess" (account_uid, space_id, permissions)
SELECT uid, id, 'editor' FROM bench_space;
INSERT INTO public."SpaceAccess" (account_uid, space_id, permissions)
SELECT '00000000-0000-4000-8000-0000000000a1', id, CASE WHEN n = 2 THEN 'reader' ELSE 'partial' END::public."SpaceAccessPermissions"
FROM bench_space WHERE n >= 2;
INSERT INTO public.group_membership (group_id, member_id, admin)
SELECT '00000000-0000-4000-8000-0000000000a1', uid, false FROM bench_space WHERE n = 1;

CREATE TEMP TABLE bench_author AS
SELECT bs.id AS space_id, nextval('public.entity_id_seq')::bigint AS id, bs.n FROM bench_space AS bs;
INSERT INTO public."PlatformAccount" (id, name, platform, account_local_id)
SELECT id, 'author' || n, 'Roam', 'author' || n FROM bench_author;
INSERT INTO public."LocalAccess" (account_id, space_id) SELECT id, space_id FROM bench_author;

INSERT INTO public."Concept" (name, space_id, author_id, source_local_id, created, last_modified, is_schema, literal_content, reference_content)
SELECT 'c' || i, a.space_id, a.id, 'l' || i, now(), now(), true, '{}', '{}'
FROM bench_author AS a, generate_series(1, 1400 * :scale) AS i;

INSERT INTO public."Document" (space_id, author_id, source_local_id, created, last_modified)
SELECT a.space_id, a.id, 'l' || i, now(), now()
FROM bench_author AS a, generate_series(1, 1400 * :scale) AS i;

INSERT INTO public."Content" (document_id, space_id, author_id, source_local_id, variant, scale, text, created, last_modified)
SELECT d.id, d.space_id, d.author_id, d.source_local_id, 'direct', 'document', 'text ' || d.source_local_id, now(), now()
FROM public."Document" AS d;

-- Grants spread over the 18 partial spaces, one resource per grant.
INSERT INTO public."ResourceAccess" (account_uid, space_id, source_local_id)
SELECT '00000000-0000-4000-8000-0000000000a1', bs.id, 'l' || (k / 18 + 1)
FROM generate_series(0, :grants - 1) AS k
JOIN bench_space AS bs ON bs.n = 3 + (k % 18);

COMMIT;
ANALYZE;
SELECT
    (SELECT count(*) FROM public."Concept") AS concepts,
    (SELECT count(*) FROM public."Content") AS contents,
    (SELECT count(*) FROM public."ResourceAccess") AS grants;
