-- Each run is rolled back by raising inside a sub-block; the timing survives in a plpgsql variable.
CREATE FUNCTION bench.time_query(phase text, label text, query text, runs int DEFAULT 7) RETURNS text
LANGUAGE plpgsql AS $$
DECLARE
    plan json;
    times numeric[] := '{}';
    row_count bigint;
BEGIN
    FOR i IN 1 .. runs + 1 LOOP
        BEGIN
            EXECUTE 'EXPLAIN (ANALYZE, FORMAT JSON) ' || query INTO plan;
            IF i > 1 THEN
                times := times || (plan -> 0 ->> 'Execution Time')::numeric;
            END IF;
            row_count := (plan -> 0 -> 'Plan' ->> 'Actual Rows')::bigint;
            RAISE EXCEPTION 'bench rollback';
        EXCEPTION WHEN raise_exception THEN
            NULL;
        END;
    END LOOP;
    RETURN format('RESULT|%s|%s|%s|%s|%s|%s', phase, label,
        round((SELECT percentile_cont(0.5) WITHIN GROUP (ORDER BY t) FROM unnest(times) AS t)::numeric, 2),
        round((SELECT min(t) FROM unnest(times) AS t), 2),
        round((SELECT max(t) FROM unnest(times) AS t), 2),
        row_count);
END;
$$;
