-- Adds concepts for measure_joins.sql. Run after generate.sql and ../rls/setup.sql.
-- Spaces 1 (own), 2 (reader) and 5 (partial) each get one concept per author, so N concepts have N distinct authors.
-- Every concept in space 5 is granted to the caller's group, so the three scopes return the same number of rows.
\set ON_ERROR_STOP 1
BEGIN;
INSERT INTO public."Concept" (name, space_id, author_id, source_local_id, created, last_modified, is_schema, literal_content, reference_content)
SELECT pa.account_local_id, la.space_id, pa.id, 'c' || lpad(split_part(pa.account_local_id, '-', 2), 5, '0'), now(), now(), true, '{}', '{}'
FROM public."PlatformAccount" AS pa
JOIN public."LocalAccess" AS la ON la.account_id = pa.id
JOIN public."Space" AS s ON s.id = la.space_id
WHERE s.name IN ('bench1', 'bench2', 'bench5') AND pa.dg_account IS NULL;

INSERT INTO public."ResourceAccess" (account_uid, space_id, source_local_id)
SELECT '00000000-0000-4000-8000-0000000000a1', c.space_id, c.source_local_id
FROM public."Concept" AS c JOIN public."Space" AS s ON s.id = c.space_id
WHERE s.name = 'bench5';

-- Ids for the batch lookups: the caller can't read them all under the old and new policies alike at setup time.
