FROM public."Concept" AS c JOIN public."Space" AS s ON s.id = c.space_id;
GRANT SELECT ON bench.space_author TO authenticated;
COMMIT;
ANALYZE;
SELECT space_name, count(*) FROM bench.space_author GROUP BY 1 ORDER BY 1;

