100	const substituteLocalReferences = (
101	  obj: any,
102	  localRefs: LocalRefsType,
103	  prefixValue: boolean = false,
104	): any => {
105	  const substituteLocalReferencesRec = (v: any): any => {
106	    if (v === undefined || v === null) return v;
107	    if (typeof v === "string") {
108	      if (prefixValue)
109	        return v.charAt(0) === "@" ? localRefs[v.substring(1)] : v;
110	      else return localRefs[v];
111	    }
112	    if (typeof v === "number" || typeof v === "boolean") return v;
113	    if (Array.isArray(v)) return v.map(substituteLocalReferencesRec);
114	    if (typeof v === "object")
115	      return Object.fromEntries(
116	        Object.entries(v as object).map(([k, v]) => [
117	          k,
118	          substituteLocalReferencesRec(v),
119	        ]),
120	      );
121	    console.error("could not substitute", typeof v, v);
122	    return v;
123	  };
124	  return substituteLocalReferencesRec(obj);
125	};
