127	const substituteLocalReferencesRow = (
128	  row: Record<string, string>,
129	  localRefs: LocalRefsType,
130	): Record<string, any> => {
131	  const processKV = ([k, v]: [string, any]): [string, any] => {
132	    const isJson = k.charAt(0) === "@";
133	    if (isJson) {
134	      k = k.substring(1);
135	      v = JSON.parse(v as string) as Json;
136	    }
137	    if (k.charAt(0) === "_") {
138	      k = k.substring(1);
139	      v = substituteLocalReferences(v, localRefs); // eslint-disable-line @typescript-eslint/no-unsafe-assignment
140	    }
141	    return [k, v];
142	  };
143	
144	  const result = Object.fromEntries(
145	    Object.entries(row)
146	      .filter(([k]: [string, string]) => k.charAt(0) !== "$")
147	      .map(processKV),
148	  );
149	  return result;
150	};
